    overflow: hidden;
    transition: transform 0.3s ease;
}

.deal-card:hover {
    transform: translateY(-2px);
}

.deal-card-1 {
    background: linear-gradient(135deg, var(--accent) 0%, #c9a227 100%);
    color: var(--background);
}

.deal-card-2 {
    background: linear-gradient(135deg, #1e40af 0%, #0c4a6e 100%);
    color: var(--text-primary);
}

.deal-card-3 {
    background: linear-gradient(135deg, var(--background-tertiary) 0%, var(--accent) 100%);
    color: var(--text-primary);
}

.deal-content h3 {
    font-size: 1.5rem;
    margin-bottom: 0.5rem;
}

.deal-discount {
    font-size: 1.75rem;
    font-weight: 700;
    margin-bottom: 0.5rem;
    letter-spacing: 1px;
}

.deal-description {
    font-size: 0.95rem;
    margin-bottom: 1.5rem;
    opacity: 0.95;
}

.deal-card .secondary-button {
    align-self: flex-start;
}

.deal-card-1 .secondary-button {
    border-color: var(--background);
    color: var(--background);
}

.deal-card-1 .secondary-button:hover {
    background-color: var(--background);
}

/* ===========================
   Editorial Section
   =========================== */

.editorial-section {
    background-color: var(--background);
}

.editorial-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
    gap: 2rem;
}

.editorial-card {
    border-radius: 8px;
