.editorial-content {
    padding: 1.5rem;
    flex-grow: 1;
    display: flex;
    flex-direction: column;
}

.editorial-content h3 {
    font-size: 1.25rem;
    margin-bottom: 0.5rem;
}

.editorial-link {
    color: var(--text-primary);
    text-decoration: none;
    transition: color 0.3s ease;
}

.editorial-link:hover,
.editorial-link:focus {
    color: var(--accent);
    outline: none;
}

.editorial-date {
    color: var(--text-tertiary);
    font-size: 0.875rem;
    margin-bottom: 1rem;
}

.editorial-excerpt {
    color: var(--text-secondary);
    font-size: 0.95rem;
    margin-bottom: 1.5rem;
    flex-grow: 1;
}

.read-more {
    color: var(--accent);
    text-decoration: none;
    font-weight: 600;
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
    transition: gap 0.3s ease, color 0.3s ease;
}

.read-more:hover,
.read-more:focus {
    gap: 0.75rem;
    outline: 2px solid var(--accent);
    outline-offset: 2px;
}

/* ===========================
   Newsletter Section
   =========================== */

.newsletter-section {
    background-color: var(--background-secondary);
    border-top: 1px solid var(--border);
}

.newsletter-section .section-container {
    text-align: center;
}

.newsletter-section h2 {
    margin-bottom: 1rem;
}

.newsletter-section > .section-container > p {
    color: var(--text-secondary);
    font-size: 1.125rem;
    margin-bottom: 2rem;
    max-width: 500px;
    margin-left: auto;
    margin-right: auto;
}

.newsletter-form {
    max-width: 500px;
    margin: 0 auto;
}

.form-group {
    display: flex;
    gap: 0.5rem;
    max-width: 100%;
}

.newsletter-form input {
    flex: 1;
    padding: 0.875rem 1rem;
    background-color: var(--background);
    border: 1px solid var(--border);
    border-radius: 4px;
    color: var(--text-primary);
    font-size: 1rem;
    transition: border-color 0.3s ease;
}

.newsletter-form input:focus {
    outline: none;
    border-color: var(--accent);
}

.newsletter-form input::placeholder {
    color: var(--text-tertiary);
}

.form-message {
    margin-top: 1rem;
    font-size: 0.95rem;
    min-height: 1.5rem;
}

.form-message.success {
    color: var(--success);
}

.form-message.error {
    color: var(--error);
}

/* ===========================
   Footer
   =========================== */

.footer {
    background-color: var(--background-secondary);
    border-top: 1px solid var(--border);
    padding: 3rem 2rem 1rem;
}

.footer-container {
    max-width: 1200px;
    margin: 0 auto;
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 2rem;
    margin-bottom: 2rem;
}

.footer-section h3 {
    font-size: 1rem;
    margin-bottom: 1rem;
    font-weight: 600;
}

.footer-section ul {
    list-style: none;
}

.footer-section ul li {
    margin-bottom: 0.75rem;
}

.footer-section a {
    color: var(--text-secondary);
    text-decoration: none;
    transition: color 0.3s ease;
}

.footer-section a:hover,
.footer-section a:focus {
    color: var(--accent);
    outline: 2px solid var(--accent);
    outline-offset: 2px;
}

.social-links {
    display: flex;
    gap: 1.5rem;
}

.footer-bottom {
    max-width: 1200px;
    margin: 0 auto;
    padding-top: 2rem;
    border-top: 1px solid var(--border);
    text-align: center;
    color: var(--text-tertiary);
    font-size: 0.9rem;
}

/* ===========================
   Responsive Design
   =========================== */

@media (max-width: 768px) {
    .hero {
        grid-template-columns: 1fr;
        padding: 2rem 1rem;
    }

    .hero-content h2 {
        font-size: 2rem;
    }

    .hero-image {
        display: none;
    }

    .nav-menu {
        display: none;
        gap: 0;
        flex-direction: column;
        position: absolute;
        top: 100%;
        left: 0;
        right: 0;
        background-color: var(--background-secondary);
        border-bottom: 1px solid var(--border);
        padding: 1rem 0;
    }

    .nav-menu.active {
        display: flex;
    }

    .nav-menu li {
        padding: 0.5rem 2rem;
    }

    .nav-toggle {
        display: flex;
    }

    .nav-toggle.active span:nth-child(1) {
        transform: rotate(-45deg) translate(-5px, 6px);
    }

    .nav-toggle.active span:nth-child(2) {
        opacity: 0;
    }

    .nav-toggle.active span:nth-child(3) {
        transform: rotate(45deg) translate(-5px, -6px);
    }

    .section-container {
        padding: 2rem 1rem;
    }

    .section-container h2 {
        font-size: 1.75rem;
    }

    .products-grid {
        grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
        gap: 1rem;
    }

    .form-group {
        flex-direction: column;
    }

    .newsletter-form input {
        width: 100%;
    }

    .newsletter-form button {
        width: 100%;
    }
}

@media (max-width: 480px) {
    .header-container {
        padding: 1rem;
    }

    .logo h1 {
        font-size: 1.25rem;
    }

    .hero-content h2 {
        font-size: 1.5rem;
    }

    .hero-content p {
        font-size: 1rem;
    }

    .products-grid {
        grid-template-columns: 1fr;
    }

    .deals-grid {
        grid-template-columns: 1fr;
    }

    .editorial-grid {
        grid-template-columns: 1fr;
    }

    .cta-button,
    .secondary-button,
    .add-to-cart {
        padding: 0.625rem 1.25rem;
        font-size: 0.95rem;
    }
}

/* ===========================
   Focus Visible States
   =========================== */

*:focus-visible {
    outline: 2px solid var(--accent);
    outline-offset: 2px;
}

button:focus-visible,
a:focus-visible {
    outline: 2px solid var(--accent);
    outline-offset: 2px;
}

/* ===========================
   Reduced Motion
   =========================== */

@media (prefers-reduced-motion: reduce) {
    *,
    *::before,
    *::after {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
        scroll-behavior: auto !important;
    }
}
