.cta-button:focus {
    outline: 2px solid var(--accent);
    outline-offset: 2px;
    background-color: var(--accent-hover);
}

.secondary-button {
    background-color: transparent;
    color: var(--accent);
    border: 2px solid var(--accent);
}

.secondary-button:hover,
.secondary-button:focus {
    background-color: var(--accent);
    color: var(--background);
}

.add-to-cart {
    background-color: transparent;
    border: 1px solid var(--border);
    color: var(--text-secondary);
    padding: 0.5rem;
    display: flex;
    align-items: center;
    justify-content: center;
}

.add-to-cart:hover,
.add-to-cart:focus {
    border-color: var(--accent);
    color: var(--accent);
}

/* ===========================
   Section Container
   =========================== */

.section-container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 4rem 2rem;
}

.section-container h2 {
    font-size: 2.5rem;
    margin-bottom: 3rem;
    text-align: center;
}

/* ===========================
   Featured Products
   =========================== */

.featured-section {
    background-color: var(--background);
}

.products-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: 2rem;
}

.product-card {
    background-color: var(--background-secondary);
    border: 1px solid var(--border);
    border-radius: 8px;
    overflow: hidden;
    transition: all 0.3s ease;
    display: flex;
    flex-direction: column;
}

.product-card:hover {
    border-color: var(--accent);
    transform: translateY(-4px);
    box-shadow: 0 8px 24px var(--shadow);
}

.product-image {
    position: relative;
    aspect-ratio: 1;
    overflow: hidden;
    background-color: var(--background-tertiary);
}

.placeholder-product {
    width: 100%;
    height: 100%;
    background: linear-gradient(135deg, #2a2a2a 0%, #1a1a1a 100%);
}

.badge {
    position: absolute;
    top: 1rem;
    right: 1rem;
    background-color: var(--accent);
    color: var(--background);
    padding: 0.375rem 0.75rem;
    border-radius: 20px;
    font-size: 0.75rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 1px;
}

.product-info {
    padding: 1.5rem;
    flex-grow: 1;
    display: flex;
    flex-direction: column;
}

.product-info h3 {
    font-size: 1.125rem;
    margin-bottom: 0.5rem;
}

.product-link {
    color: var(--text-primary);
    text-decoration: none;
    transition: color 0.3s ease;
}

.product-link:hover,
.product-link:focus {
    color: var(--accent);
    outline: none;
}

.product-category {
    color: var(--text-tertiary);
    font-size: 0.875rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    margin-bottom: 0.5rem;
}

.product-description {
    color: var(--text-secondary);
    font-size: 0.95rem;
    margin-bottom: 1.5rem;
    flex-grow: 1;
}

.product-footer {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding-top: 1rem;
    border-top: 1px solid var(--border);
}

.price {
    font-size: 1.375rem;
    font-weight: 700;
    color: var(--accent);
}

.price-group {
    display: flex;
    gap: 0.75rem;
    align-items: center;
}

.original-price {
    color: var(--text-tertiary);
    text-decoration: line-through;
    font-size: 0.95rem;
}

/* ===========================
   Deals Section
   =========================== */

.deals-section {
    background-color: var(--background-secondary);
    border-top: 1px solid var(--border);
    border-bottom: 1px solid var(--border);
}

.deals-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: 2rem;
}

.deal-card {
    border-radius: 8px;
    padding: 2rem;
    display: flex;
    flex-direction: column;
    justify-content: center;
    min-height: 200px;
    position: relative;
    overflow: hidden;
    transition: transform 0.3s ease;
}

.deal-card:hover {
    transform: translateY(-2px);
}

.deal-card-1 {
    background: linear-gradient(135deg, var(--accent) 0%, #c9a227 100%);
    color: var(--background);
}

.deal-card-2 {
    background: linear-gradient(135deg, #1e40af 0%, #0c4a6e 100%);
    color: var(--text-primary);
}

.deal-card-3 {
    background: linear-gradient(135deg, var(--background-tertiary) 0%, var(--accent) 100%);
    color: var(--text-primary);
}

.deal-content h3 {
    font-size: 1.5rem;
    margin-bottom: 0.5rem;
}

.deal-discount {
    font-size: 1.75rem;
    font-weight: 700;
    margin-bottom: 0.5rem;
    letter-spacing: 1px;
}

.deal-description {
    font-size: 0.95rem;
    margin-bottom: 1.5rem;
    opacity: 0.95;
}

.deal-card .secondary-button {
    align-self: flex-start;
}

.deal-card-1 .secondary-button {
    border-color: var(--background);
    color: var(--background);
}

.deal-card-1 .secondary-button:hover {
    background-color: var(--background);
}

/* ===========================
   Editorial Section
   =========================== */

.editorial-section {
    background-color: var(--background);
}

.editorial-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
    gap: 2rem;
}

.editorial-card {
    border-radius: 8px;
    overflow: hidden;
    background-color: var(--background-secondary);
    border: 1px solid var(--border);
    transition: all 0.3s ease;
    display: flex;
    flex-direction: column;
}

.editorial-card:hover {
    border-color: var(--accent);
    box-shadow: 0 8px 24px var(--shadow);
}

.editorial-image {
    aspect-ratio: 16 / 9;
    overflow: hidden;
    background-color: var(--background-tertiary);
}

.placeholder-editorial {
    width: 100%;
    height: 100%;
    background: linear-gradient(135deg, #333333 0%, #2a2a2a 100%);
}

.editorial-content {
    padding: 1.5rem;
    flex-grow: 1;
    display: flex;
    flex-direction: column;
}

.editorial-content h3 {
    font-size: 1.25rem;
    margin-bottom: 0.5rem;
}

.editorial-link {
    color: var(--text-primary);
    text-decoration: none;
    transition: color 0.3s ease;
}

.editorial-link:hover,
.editorial-link:focus {
    color: var(--accent);
    outline: none;
}

.editorial-date {
    color: var(--text-tertiary);
    font-size: 0.875rem;
    margin-bottom: 1rem;
}

.editorial-excerpt {
    color: var(--text-secondary);
    font-size: 0.95rem;
    margin-bottom: 1.5rem;
    flex-grow: 1;
}

.read-more {
    color: var(--accent);
    text-decoration: none;
    font-weight: 600;
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
    transition: gap 0.3s ease, color 0.3s ease;
}

.read-more:hover,
.read-more:focus {
    gap: 0.75rem;
    outline: 2px solid var(--accent);
    outline-offset: 2px;
}

/* ===========================
   Newsletter Section
   =========================== */

.newsletter-section {
    background-color: var(--background-secondary);
    border-top: 1px solid var(--border);
}

.newsletter-section .section-container {
    text-align: center;
}

.newsletter-section h2 {
    margin-bottom: 1rem;
}

.newsletter-section > .section-container > p {
    color: var(--text-secondary);
    font-size: 1.125rem;
    margin-bottom: 2rem;
    max-width: 500px;
    margin-left: auto;
    margin-right: auto;
}

.newsletter-form {
    max-width: 500px;
    margin: 0 auto;
}

.form-group {
    display: flex;
    gap: 0.5rem;
    max-width: 100%;
}

.newsletter-form input {
    flex: 1;
    padding: 0.875rem 1rem;
    background-color: var(--background);
    border: 1px solid var(--border);
    border-radius: 4px;
    color: var(--text-primary);
    font-size: 1rem;
    transition: border-color 0.3s ease;
}

.newsletter-form input:focus {
    outline: none;
    border-color: var(--accent);
}

.newsletter-form input::placeholder {
    color: var(--text-tertiary);
}

.form-message {
    margin-top: 1rem;
    font-size: 0.95rem;
    min-height: 1.5rem;
}

.form-message.success {
    color: var(--success);
}

.form-message.error {
    color: var(--error);
}

/* ===========================
   Footer
   =========================== */

.footer {
    background-color: var(--background-secondary);
    border-top: 1px solid var(--border);
    padding: 3rem 2rem 1rem;
}

.footer-container {
    max-width: 1200px;
    margin: 0 auto;
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 2rem;
    margin-bottom: 2rem;
}

.footer-section h3 {
    font-size: 1rem;
    margin-bottom: 1rem;
    font-weight: 600;
}

.footer-section ul {
    list-style: none;
}

.footer-section ul li {
    margin-bottom: 0.75rem;
}

.footer-section a {
    color: var(--text-secondary);
    text-decoration: none;
    transition: color 0.3s ease;
}

.footer-section a:hover,
.footer-section a:focus {
    color: var(--accent);
    outline: 2px solid var(--accent);
    outline-offset: 2px;
}

.social-links {
    display: flex;
    gap: 1.5rem;
}

.footer-bottom {
    max-width: 1200px;
    margin: 0 auto;
    padding-top: 2rem;
    border-top: 1px solid var(--border);
    text-align: center;
    color: var(--text-tertiary);
    font-size: 0.9rem;
}

/* ===========================
   Responsive Design
   =========================== */

@media (max-width: 768px) {
    .hero {
        grid-template-columns: 1fr;
        padding: 2rem 1rem;
    }

    .hero-content h2 {
        font-size: 2rem;
    }

    .hero-image {
        display: none;
    }

    .nav-menu {
        display: none;
        gap: 0;
        flex-direction: column;
        position: absolute;
        top: 100%;
        left: 0;
        right: 0;
        background-color: var(--background-secondary);
        border-bottom: 1px solid var(--border);
        padding: 1rem 0;
    }

    .nav-menu.active {
        display: flex;
    }

    .nav-menu li {
        padding: 0.5rem 2rem;
    }

    .nav-toggle {
        display: flex;
    }

    .nav-toggle.active span:nth-child(1) {
        transform: rotate(-45deg) translate(-5px, 6px);
    }

    .nav-toggle.active span:nth-child(2) {
        opacity: 0;
    }

    .nav-toggle.active span:nth-child(3) {
        transform: rotate(45deg) translate(-5px, -6px);
    }

    .section-container {
        padding: 2rem 1rem;
    }

    .section-container h2 {
        font-size: 1.75rem;
    }

    .products-grid {
        grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
        gap: 1rem;
    }

    .form-group {
        flex-direction: column;
    }

    .newsletter-form input {
        width: 100%;
    }

    .newsletter-form button {
        width: 100%;
    }
}

@media (max-width: 480px) {
    .header-container {
        padding: 1rem;
    }

    .logo h1 {
        font-size: 1.25rem;
    }

    .hero-content h2 {
        font-size: 1.5rem;
    }

    .hero-content p {
        font-size: 1rem;
    }

    .products-grid {
        grid-template-columns: 1fr;
    }

    .deals-grid {
        grid-template-columns: 1fr;
    }

    .editorial-grid {
        grid-template-columns: 1fr;
    }

    .cta-button,
    .secondary-button,
    .add-to-cart {
        padding: 0.625rem 1.25rem;
        font-size: 0.95rem;
    }
}

/* ===========================
   Focus Visible States
   =========================== */

*:focus-visible {
    outline: 2px solid var(--accent);
    outline-offset: 2px;
}

button:focus-visible,
a:focus-visible {
    outline: 2px solid var(--accent);
    outline-offset: 2px;
}

/* ===========================
   Reduced Motion
   =========================== */

@media (prefers-reduced-motion: reduce) {
    *,
    *::before,
    *::after {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
        scroll-behavior: auto !important;
    }
}

