   =========================== */

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

:root {
    --primary: #ffffff;
    --primary-dark: #f5f5f5;
    --background: #0f0f0f;
    --background-secondary: #1a1a1a;
    --background-tertiary: #2a2a2a;
    --accent: #d4af37;
    --accent-hover: #e5c158;
    --text-primary: #ffffff;
    --text-secondary: #b0b0b0;
    --text-tertiary: #808080;
    --border: #333333;
    --success: #4ade80;
    --error: #ef4444;
    --shadow: rgba(0, 0, 0, 0.5);
}

html {
    scroll-behavior: smooth;
}

body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Helvetica Neue', sans-serif;
    background-color: var(--background);
    color: var(--text-primary);
    line-height: 1.6;
    letter-spacing: 0.3px;
}

/* ===========================
   Accessibility
   =========================== */

.skip-link {
    position: absolute;
    top: -40px;
    left: 0;
    background: var(--accent);
    color: var(--background);
    padding: 8px;
    text-decoration: none;
    font-weight: 600;
    z-index: 100;
}

.skip-link:focus {
    top: 0;
}

.sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border-width: 0;
}

/* ===========================
   Header & Navigation
   =========================== */

.header {
    background-color: var(--background-secondary);
    border-bottom: 1px solid var(--border);
    position: sticky;
    top: 0;
    z-index: 50;
}

.header-container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 1rem 2rem;
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.logo h1 {
    font-size: 1.5rem;
    font-weight: 700;
    letter-spacing: 2px;
}

.navigation {
    flex: 1;
    margin: 0 2rem;
}

.nav-menu {
    display: flex;
    list-style: none;
    gap: 2rem;
}

.nav-menu a {
    color: var(--text-secondary);
    text-decoration: none;
    font-weight: 500;
    font-size: 0.95rem;
    transition: color 0.3s ease;
}

.nav-menu a:hover,
.nav-menu a:focus {
    color: var(--accent);
    outline: none;
}

.nav-menu a:focus {
    outline: 2px solid var(--accent);
    outline-offset: 4px;
}

.nav-toggle {
    display: none;
    flex-direction: column;
    background: none;
    border: none;
    cursor: pointer;
    padding: 0.5rem;
}

.nav-toggle span {
    width: 24px;
    height: 2px;
    background-color: var(--text-primary);
    margin: 4px 0;
    transition: 0.3s;
    display: block;
}

.cart-icon button {
    background: none;
    border: none;
    color: var(--text-primary);
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 0.5rem;
    transition: color 0.3s ease;
}

.cart-icon button:hover,
.cart-icon button:focus {
    color: var(--accent);
    outline: 2px solid var(--accent);
    outline-offset: 4px;
}

/* ===========================
   Hero Section
   =========================== */

.hero {
    display: grid;
    grid-template-columns: 1fr 1fr;
    align-items: center;
    gap: 3rem;
    padding: 4rem 2rem;
    max-width: 1200px;
    margin: 0 auto;
}

.hero-content h2 {
    font-size: 3rem;
    font-weight: 700;
    margin-bottom: 1rem;
    line-height: 1.2;
}

.hero-content p {
    font-size: 1.125rem;
    color: var(--text-secondary);
    margin-bottom: 2rem;
}

.hero-image {
    aspect-ratio: 1;
    border-radius: 8px;
    overflow: hidden;
}

.placeholder-image {
    width: 100%;
    height: 100%;
    background: linear-gradient(135deg, var(--background-tertiary) 0%, var(--accent) 100%);
}

/* ===========================
   Buttons
   =========================== */

.cta-button,
.secondary-button,
.add-to-cart {
    border: none;
    border-radius: 4px;
    font-size: 1rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.3s ease;
    letter-spacing: 0.5px;
    padding: 0.75rem 1.5rem;
}

.cta-button {
    background-color: var(--accent);
    color: var(--background);
}

.cta-button:hover {
    background-color: var(--accent-hover);
    transform: translateY(-2px);
}

.cta-button:focus {
    outline: 2px solid var(--accent);
    outline-offset: 2px;
    background-color: var(--accent-hover);
}

.secondary-button {
    background-color: transparent;
    color: var(--accent);
    border: 2px solid var(--accent);
}

.secondary-button:hover,
.secondary-button:focus {
    background-color: var(--accent);
    color: var(--background);
}

.add-to-cart {
    background-color: transparent;
    border: 1px solid var(--border);
    color: var(--text-secondary);
    padding: 0.5rem;
    display: flex;
    align-items: center;
    justify-content: center;
}

.add-to-cart:hover,
.add-to-cart:focus {
    border-color: var(--accent);
    color: var(--accent);
}

/* ===========================
   Section Container
   =========================== */

.section-container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 4rem 2rem;
}

.section-container h2 {
    font-size: 2.5rem;
    margin-bottom: 3rem;
    text-align: center;
}

/* ===========================
   Featured Products
   =========================== */

.featured-section {
    background-color: var(--background);
}

.products-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: 2rem;
}

.product-card {
    background-color: var(--background-secondary);
    border: 1px solid var(--border);
    border-radius: 8px;
    overflow: hidden;
    transition: all 0.3s ease;
    display: flex;
    flex-direction: column;
}

.product-card:hover {
    border-color: var(--accent);
    transform: translateY(-4px);
    box-shadow: 0 8px 24px var(--shadow);
}

.product-image {
    position: relative;
    aspect-ratio: 1;
    overflow: hidden;
    background-color: var(--background-tertiary);
}

.placeholder-product {
    width: 100%;
    height: 100%;
    background: linear-gradient(135deg, #2a2a2a 0%, #1a1a1a 100%);
}

.badge {
    position: absolute;
    top: 1rem;
    right: 1rem;
    background-color: var(--accent);
