}

.deal-description {
    font-size: 0.95rem;
    margin-bottom: 1.5rem;
    opacity: 0.95;
}

.deal-card .secondary-button {
    align-self: flex-start;
}

.deal-card-1 .secondary-button {
    border-color: var(--background);
